from typing import List

def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    k = 1  # Sliding window size
    rolling_maxs = []

    for i in range(len(numbers) - k + 1):
        window = numbers[i:i+k]
        rolling_maxs.append(max(window))

    return rolling_maxs
